import {validateCue,validateTarget,targetAnchor,compileMotion,sampleMotion,cameraAt} from './motion.js';
const clone=x=>structuredClone(x),ns='http://www.w3.org/2000/svg';
export function initMotionUI({$,canvas,getBoard,getView,getTarget,blocked,beforeOpen,preview,saveCue,commitGeometry,prepareRegion,validate,status}){
 const panel=$('motion-panel'),stage=$('motion-stage'),transport=$('motion-transport');
 let opened=false,base=null,originalView=null,target=null,draft=null,capture=null,drag=null,session=null,index=0,progress=0,running=false,paused=false,automatic=false,raf=0,started=0,fromProgress=0,lastFrame=null,inert=[];
 const size=()=>({width:canvas.clientWidth,height:canvas.clientHeight});
 const consume=e=>{e.preventDefault();e.stopImmediatePropagation();};
 function assertCurrent(){if(getBoard()!==base)throw Error('Board changed · close and reopen Motion Trace');}
 function error(e){$('motion-error').textContent=e.message||String(e);status(e.message||String(e),true);}
 function clearError(){$('motion-error').textContent='';}
 function rememberBase(){base=getBoard();}
 function newMove(){stop();target=target||getTarget();if(!target)throw Error('Select artwork with lasso, or open Motion Trace from a folder');validateTarget(target);targetAnchor(base,target);draft={id:crypto.randomUUID(),name:'Artwork motion',kind:'move',target:clone(target),path:[{x:0,y:0},{x:80,y:0}],duration:2000};populate();}
 function newCamera(){stop();draft={id:crypto.randomUUID(),name:'Camera view',kind:'camera',target:cameraAt(originalView,size()),duration:2000};populate();}
 function populate(){clearError();$('motion-name').value=draft?.name||'';$('motion-seconds').value=(draft?.duration||2000)/1000;$('motion-move-fields').hidden=draft?.kind!=='move';$('motion-camera-fields').hidden=draft?.kind!=='camera';if(draft?.kind==='move'){const end=draft.path.at(-1);$('motion-x').value=end.x;$('motion-y').value=end.y;$('motion-point-count').textContent=draft.path.length+' / 128 path points';$('motion-target').textContent=draft.target.kind==='region'?'Target: selected pixels · committing converts the affected layer undoably':draft.target.kind==='folder'?'Target: folder contents and leaf masks':'Target: '+draft.target.ids.length+' selected objects · masks stay in place';}else if(draft){for(const k of ['x','y','scale'])$('motion-camera-'+k).value=draft.target[k];$('motion-target').textContent='Audience camera · artwork stays in place';}else $('motion-target').textContent='Select artwork, add a camera cue, or choose a saved cue.';list();sync();}
 function read(){if(!draft)throw Error('Add or select a cue first');const c=clone(draft);c.name=$('motion-name').value;c.duration=Number($('motion-seconds').value)*1000;if(c.kind==='camera')for(const k of ['x','y','scale'])c.target[k]=Number($('motion-camera-'+k).value);else{const x=$('motion-x').value,y=$('motion-y').value;if(x===''||y==='')throw Error('Enter a path endpoint');c.path[c.path.length-1]={x:Number(x),y:Number(y)};}validateCue(c);return c;}
 function list(){const list=$('motion-cues'),previous=draft?.id;list.replaceChildren();for(const [i,c]of(base.motion?.cues||[]).entries()){const o=document.createElement('option');o.value=c.id;o.textContent=(i+1)+'. '+c.name+(c.kind==='camera'?' · camera':' · move');list.append(o);}list.value=previous||'';const cues=base.motion?.cues||[];list.hidden=!cues.length;$('motion-order-row').hidden=!cues.length;$('motion-delete').disabled=!cues.some(c=>c.id===previous);$('motion-up').disabled=cues.findIndex(c=>c.id===previous)<=0;$('motion-down').disabled=!cues.some(c=>c.id===previous)||cues.findIndex(c=>c.id===previous)>=cues.length-1;$('motion-present').disabled=!cues.length;$('motion-saved-count').textContent=(base.motion?.cues.length||0)+' / 24 saved cues';}
 function sync(){
  if(!opened)return;const presenting=!!session;panel.hidden=presenting||!!capture;transport.hidden=!presenting;$('motion-capture-bar').hidden=!capture;stage.removeAttribute('hidden');const rect=canvas.getBoundingClientRect();Object.assign(stage.style,{left:rect.x+'px',top:rect.y+'px',width:rect.width+'px',height:rect.height+'px',right:'auto',bottom:'auto'});stage.dataset.mode=capture|| (presenting?'present':'idle');stage.replaceChildren();
  $('motion-next').disabled=!session||running||paused||index>=session.segments.length;$('motion-pause').disabled=!running;$('motion-resume').disabled=!paused;$('motion-commit').disabled=!session||running||!lastFrame;
  $('motion-play-state').textContent=session?(index>=session.segments.length?'Complete · ':paused?'Paused · ':running?'Playing · ':'Ready · ')+Math.min(index+1,session.segments.length)+' / '+session.segments.length+' · '+Math.round(progress*100)+'%':'';
  if(!presenting&&draft?.kind==='move'){try{const anchor=targetAnchor(base,draft.target),v=getView(),points=draft.path.map(p=>(anchor.x+p.x)*v.scale+v.x+','+((anchor.y+p.y)*v.scale+v.y));const poly=document.createElementNS(ns,'polyline');poly.setAttribute('points',points.join(' '));poly.setAttribute('class','motion-path');stage.append(poly);for(const p of [draft.path[0],draft.path.at(-1)]){const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx',(anchor.x+p.x)*v.scale+v.x);circle.setAttribute('cy',(anchor.y+p.y)*v.scale+v.y);circle.setAttribute('r','5');circle.setAttribute('class','motion-endpoint');stage.append(circle);}}catch(e){error(e);}}
 }
 function restore(){preview(null,originalView);lastFrame=null;}
 function stop(){cancelAnimationFrame(raf);raf=0;session=null;running=false;paused=false;index=0;progress=0;capture=null;drag=null;if(opened){restore();sync();$('motion-heading').focus();}}
 function close(){if(!opened)return;stop();opened=false;panel.hidden=true;stage.setAttribute('hidden','');transport.hidden=true;$('motion-capture-bar').hidden=true;document.body.classList.remove('motion-open');for(const[el,value]of inert)el.inert=value;inert=[];draft=null;target=null;$('actions-toggle').focus();status('Motion Trace closed · original layout and view restored');}
 function open(folderId=null){if(opened||blocked())return;try{beforeOpen();base=getBoard();originalView=clone(getView());target=folderId?{kind:'folder',id:folderId}:getTarget();opened=true;document.body.classList.add('motion-open');inert=[...document.querySelectorAll('header,aside,.popover,#quick-transform,#mask-controls,#path-quick-controls')].map(el=>[el,el.inert]);for(const[el]of inert)el.inert=true;draft=null;const first=base.motion?.cues[0];if(target)newMove();else if(first){draft=clone(first);populate();}else newCamera();$('motion-mode').value='manual';panel.hidden=false;$('motion-heading').focus();}catch(e){if(opened)close();error(e);}}
 function render(){assertCurrent();lastFrame=sampleMotion(session,Math.min(index,session.segments.length-1),progress);preview(lastFrame.board,lastFrame.view);sync();}
 function tick(now){if(!running||!session)return;try{progress=Math.max(fromProgress,Math.min(1,fromProgress+(now-started)/session.segments[index].cue.duration));render();if(progress===1){running=false;paused=false;index++;progress=0;if(automatic&&index<session.segments.length)advance();else sync();}else raf=requestAnimationFrame(tick);}catch(e){stop();error(e);}}
 function advance(){if(!session||running||paused||index>=session.segments.length)return;running=true;started=performance.now();fromProgress=progress;sync();raf=requestAnimationFrame(tick);}
 function pause(){if(!running)return;cancelAnimationFrame(raf);running=false;paused=true;sync();}
 function resume(){if(!paused||!session)return;assertCurrent();paused=false;running=true;fromProgress=progress;started=performance.now();sync();raf=requestAnimationFrame(tick);}
 function present(cues,auto){stop();assertCurrent();session=compileMotion(base,cues,originalView,size(),prepareRegion);for(let i=0;i<session.segments.length;i++){validate(session.segments[i].base);validate(sampleMotion(session,i,1).board);}automatic=auto;index=0;progress=0;render();if(auto){advance();$('motion-pause').focus();}else $('motion-next').focus();}
 function safely(fn){return()=>{try{assertCurrent();clearError();fn();}catch(e){error(e);}};}
 $('motion-open').onclick=()=>open();$('trace-selection').onclick=()=>open();$('motion-close').onclick=close;
 $('motion-new-move').onclick=safely(newMove);$('motion-new-camera').onclick=safely(newCamera);
 $('motion-use-selection').onclick=safely(()=>{stop();target=getTarget();if(!target)throw Error('Close Motion Trace and select artwork first');if(draft?.kind!=='move')newMove();else{draft.target=clone(target);populate();}});
 $('motion-cues').onchange=safely(()=>{stop();draft=clone(base.motion.cues.find(c=>c.id===$('motion-cues').value));populate();});
 $('motion-save').onclick=safely(()=>{stop();const cue=read();saveCue('save',cue,base);rememberBase();draft=clone(cue);populate();status('Motion cue saved · artwork unchanged · Undo restores prior cues');});
 for(const action of ['delete','up','down'])$('motion-'+action).onclick=safely(()=>{stop();if(!draft)throw Error('Choose a saved cue');saveCue(action,draft.id,base);rememberBase();draft=clone(base.motion?.cues.find(c=>c.id===draft.id)||base.motion?.cues[0]||null);populate();});
 $('motion-preview').onclick=safely(()=>present([read()],true));$('motion-present').onclick=safely(()=>present(base.motion?.cues||[],$('motion-mode').value==='timed'));
 $('motion-next').onclick=safely(advance);$('motion-pause').onclick=pause;$('motion-resume').onclick=safely(resume);$('motion-stop').onclick=()=>{stop();status('Presentation stopped · original layout and view restored');};
 $('motion-commit').onclick=safely(()=>{if(!session||!lastFrame||running)throw Error('Pause or finish playback before committing');const frame=lastFrame;stop();const changed=frame.hasGeometry?commitGeometry(frame.board,base):false;rememberBase();populate();status(changed?'Motion position committed · Undo restores original artwork':'No artwork movement · original artwork unchanged');});
 $('motion-draw').onclick=safely(()=>{stop();draft=read();if(draft.kind!=='move')throw Error('Select an artwork cue');capture='path';sync();stage.focus();});
 $('motion-pick-camera').onclick=safely(()=>{stop();draft=read();capture='camera';sync();stage.focus();});
 $('motion-capture-done').onclick=()=>{capture=null;drag=null;populate();};$('motion-capture-cancel').onclick=()=>{if(drag?.before)draft.path=drag.before;capture=null;drag=null;populate();};
 for(const id of ['motion-x','motion-y'])$(id).oninput=safely(()=>{const value=read();draft.path=value.path;sync();});
 const point=e=>{const rect=canvas.getBoundingClientRect(),v=getView();return{x:(e.clientX-rect.x-v.x)/v.scale,y:(e.clientY-rect.y-v.y)/v.scale};};
 stage.addEventListener('pointerdown',e=>{if(!opened)return;consume(e);if(!capture||e.button!==0)return;if(e.pointerType==='touch'){status('Use pen or mouse to define a path; numeric endpoints work with touch');return;}try{assertCurrent();if(capture==='camera'){draft.target.x=point(e).x;draft.target.y=point(e).y;capture=null;populate();return;}drag={id:e.pointerId,origin:point(e),before:clone(draft.path)};draft.path=[{x:0,y:0}];stage.setPointerCapture(e.pointerId);sync();}catch(err){error(err);}});
 stage.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;consume(e);const p=point(e),q={x:p.x-drag.origin.x,y:p.y-drag.origin.y},last=draft.path.at(-1);if(Math.hypot(q.x-last.x,q.y-last.y)*getView().scale<4)return;if(draft.path.length>=128){status('128 path points reached · release to finish',true);return;}draft.path.push(q);$('motion-x').value=q.x;$('motion-y').value=q.y;sync();});
 function finish(e,cancelled=false){if(!drag||drag.id!==e.pointerId)return;consume(e);const done=drag;drag=null;if(cancelled||draft.path.length<2)draft.path=done.before;capture=null;try{stage.releasePointerCapture(e.pointerId);}catch{}populate();}
 stage.addEventListener('pointerup',e=>finish(e));stage.addEventListener('pointercancel',e=>finish(e,true));stage.addEventListener('lostpointercapture',e=>finish(e,true));stage.addEventListener('wheel',e=>{if(opened)consume(e);},{passive:false});
 window.addEventListener('keydown',e=>{if(!opened)return;e.stopImmediatePropagation();if(e.key==='Escape'){consume(e);if(session||capture)stop();else close();return;}if(session){if(e.code==='Space'){consume(e);running?pause():paused?resume():advance();}else if(['ArrowRight','Enter'].includes(e.key)&&!e.target.closest('button')){consume(e);advance();}else if(!e.target.closest('#motion-transport'))consume(e);}else if(!e.target.closest('#motion-panel,#motion-stage,#motion-capture-bar'))consume(e);
  if(e.key==='Tab'){const region=session?transport:capture?$('motion-capture-bar'):panel,items=[...region.querySelectorAll('button,input,select,[tabindex]')].filter(el=>!el.disabled&&!el.hidden&&el.getClientRects().length);if(items.length&&(e.shiftKey&&document.activeElement===items[0]||!e.shiftKey&&document.activeElement===items.at(-1))){consume(e);(e.shiftKey?items.at(-1):items[0]).focus();}}
 },true);
 window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('resize',()=>{if(session){stop();status('Viewport changed · presentation restored; start again');}else if(opened)sync();});
 return{open,close,editing:()=>opened,stop};
}
